[
  {
    "statement": "A laboratory study evaluated the effects of using genetically modified crops that produce their own pesticide instead of conventional pesticide application.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "A study found that pollen from genetically modified maize expressing the Btk (Bacillus thuringiensis kurstaki) toxin did not reduce the survival of eastern tiger swallowtail or spicebush swallowtail caterpillars when compared to pollen from non-genetically modified maize.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "A study found that pollen from genetically modified maize expressing the Btk (Bacillus thuringiensis kurstaki) toxin did not reduce the growth of eastern tiger swallowtail or spicebush swallowtail caterpillars when compared to pollen from non-genetically modified maize.",
    "citations": [
      "3895"
    ]
  }
]

[
  {
    "statement": "A study in Switzerland found that using mass-emergence devices in urban areas resulted in higher parasitism at one site but had no effect at another.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "Using mass-emergence devices had no overall impact on pest damage to horse chestnut trees in one Swiss study.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "In a study from the USA and an unspecified Mediterranean country, adding compost to the soil was found to reduce crop disease in some comparisons.",
    "citations": [
      "1392"
    ]
  },
  {
    "statement": "Another study showed adding compost to soil made no difference to crop disease.",
    "citations": [
      "1392"
    ]
  },
  {
    "statement": "A study noted fewer dead tomato plants in soil with added compost in some cases.",
    "citations": [
      "1392"
    ]
  },
  {
    "statement": "Three US and Italian studies found that planting flower strips increased pest reduction.",
    "citations": [
      "1400"
    ]
  },
  {
    "statement": "Three US and Italian studies found that planting flower strips increased the proportion of parasitized pests.",
    "citations": [
      "1400"
    ]
  },
  {
    "statement": "An Italian study reported more damage by caterpillars in tomatoes near flower strips.",
    "citations": [
      "1400"
    ]
  },
  {
    "statement": "Delaying herbicide use, as studied in Australia and Denmark, led to an increase in natural enemies.",
    "citations": [
      "774"
    ]
  },
  {
    "statement": "Delaying herbicide use, as studied in Australia and Denmark, also led to more weeds.",
    "citations": [
      "774"
    ]
  },
  {
    "statement": "The effects of delaying herbicide use on insect pests and crop damage were inconsistent.",
    "citations": [
      "774"
    ]
  },
  {
    "statement": "One study on delaying herbicide use found lower yields while another found no effect.",
    "citations": [
      "774"
    ]
  },
  {
    "statement": "No information was found regarding the cost-effectiveness of certain natural pest control methods in arid or desert environments.",
    "citations": [
      "775",
      "1392",
      "1400",
      "774"
    ]
  },
  {
    "statement": "No studies were found on the effects on bat populations of managing natural water bodies to prevent desiccation.",
    "citations": [
      "2027"
    ]
  },
  {
    "statement": "No studies were found on the effects on butterflies and moths of managing natural water bodies to prevent desiccation.",
    "citations": [
      "3858"
    ]
  }
]

[
  {
    "statement": "A study in Switzerland on the use of mass-emergence devices in urban areas found that parasitism was higher at one site.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "A study in Switzerland on the use of mass-emergence devices in urban areas found the devices had no effect on parasitism at another site.",
    "citations": [
      "775"
    ]
  },
  {
    "statement": "A Swiss study on the use of mass-emergence devices found there was no effect on pest damage to horse chestnut trees.",
    "citations": [
      "775"
    ]
  }
]

[
  {
    "statement": "One method of pest control is alley cropping.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "Four studies from Kenya and the USA found that the effects of alley cropping on parasitism varied between study sites, sampling dates, pest life stages or the width of crop alleys.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "Two studies found alley cropping had no effect on parasitism.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "One study found alley cropping had mixed effects on fungal infections in pests.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "One study found lower egg predation in areas with alley cropping.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "Another study found more wasps and spiders but fewer ladybirds in areas with alley cropping.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "Two of four studies found more pests in alley cropped plots.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "One study found fewer pests in alley cropped plots.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "One study found the effects of alley cropping on pests varied with the pest group and between years.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "One study found more pest damage to crops with alley cropping.",
    "citations": [
      "718"
    ]
  },
  {
    "statement": "Another study found alley cropping had no effect on pest damage to crops.",
    "citations": [
      "718"
    ]
  }
]
